"use client";

import { useState } from "react";
import { Dialog, DialogContent, DialogTitle } from "@/components/ui/dialog"; 
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";

// De templates die jij wilde
const TEMPLATES = [
  { id: "review", name: "Sprint Review" },
  { id: "retrospective", name: "Sprint Retrospective" },
  { id: "release", name: "Release Planning" },
  { id: "sprintplan", name: "Sprint Planning" },
  { id: "daily", name: "Daily Scrum" },
];

export default function TaskFormModal({ open, setOpen, onCreateTask }: any) {
  const [titel, setTitel] = useState("");
  const [templateId, setTemplateId] = useState("review");
  const [sprint, setSprint] = useState(1);
  const [datum, setDatum] = useState(new Date().toISOString().split('T')[0]);

  function handleSubmit() {
    if (!titel) return alert("Voer een titel in!");

    const nieuweTaak = {
      id: Date.now(),
      titel: titel,
      documentType: templateId,
      sprint: sprint,
      datum: datum,
      // Lege velden die per template gevuld worden
      content1: "",
      content2: "",
      content3: "",
    };

    onCreateTask(nieuweTaak);
    setTitel("");
    setOpen(false);
  }

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogContent className="bg-[#0E153A]/95 border border-teal-400/30 text-teal-100 p-6 rounded-2xl shadow-2xl backdrop-blur-xl">
        <DialogTitle className="text-2xl font-bold text-teal-300 mb-4 font-mono uppercase tracking-tighter">
          Nieuw Scrum Document
        </DialogTitle>
        
        <div className="flex flex-col gap-5">
          <div>
            <label className="text-[10px] text-teal-500 font-bold uppercase tracking-widest block mb-1">Selecteer Template</label>
            <select 
              value={templateId} 
              onChange={(e) => setTemplateId(e.target.value)}
              className="w-full bg-[#0b1233] border border-teal-400/30 rounded-md p-2 text-sm text-teal-200 focus:border-fuchsia-500 outline-none"
            >
              {TEMPLATES.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}
            </select>
          </div>

          <div>
            <label className="text-[10px] text-teal-500 font-bold uppercase tracking-widest block mb-1">Document Titel</label>
            <Input value={titel} onChange={(e) => setTitel(e.target.value)} placeholder="Bijv. Review Sprint 1" className="bg-[#0b1233] border-teal-400/30 text-white" />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="text-[10px] text-teal-500 font-bold uppercase tracking-widest block mb-1">Sprint</label>
              <Input type="number" value={sprint} onChange={(e) => setSprint(+e.target.value)} className="bg-[#0b1233] border-teal-400/30 text-white" />
            </div>
            <div>
              <label className="text-[10px] text-teal-500 font-bold uppercase tracking-widest block mb-1">Datum</label>
              <Input type="date" value={datum} onChange={(e) => setDatum(e.target.value)} className="bg-[#0b1233] border-teal-400/30 text-white" />
            </div>
          </div>

          <Button onClick={handleSubmit} className="bg-gradient-to-r from-teal-400 to-fuchsia-500 text-black font-black uppercase tracking-widest mt-2 hover:scale-[1.02] transition-transform">
            Document Aanmaken
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}