"use client";

import { useState } from "react";
import { Card, CardHeader, CardTitle, CardDescription, CardContent } from "@/components/ui/Card";
import { Button } from "@/components/ui/button";
import TaskFormModal from "@/components/tasks/TaskFormModal";
import { Textarea } from "@/components/ui/textarea";

export default function TasksPage() {
  const [open, setOpen] = useState(false);  
  const [items, setItems] = useState<any[]>([]);  
  const [geselecteerdItem, setGeselecteerdItem] = useState<any>(null);

  const getQuestions = (type: string) => {
    switch(type) {
      case 'review': return ["Wat heb jij gemaakt/geleerd?", "Wat beheers jij nog niet voldoende?", "Actiepunten voor volgende Sprint"];
      case 'retrospective': return ["Wat ging er goed?", "Wat kon er beter?", "Verbeterpunten teamproces"];
      case 'sprintplan': return ["Wat is het Sprint Doel?", "Welke User Stories pakken we op?", "Verwachte roadblocks"];
      case 'daily': return ["Wat heb je gisteren gedaan?", "Wat ga je vandaag doen?", "Zijn er blokkades?"];
      case 'release': return ["Belangrijkste milestones", "Afhankelijkheden", "Grootste risico's"];
      default: return ["Inhoud", "Opmerkingen", "Extra info"];
    }
  };

  function handleCreate(nieuwItem: any) {
    setItems((prev) => [nieuwItem, ...prev]);
    setGeselecteerdItem(nieuwItem);
  }

  function updateContent(veld: string, waarde: string) {
    if (!geselecteerdItem) return;
    const nieuweLijst = items.map(item => item.id === geselecteerdItem.id ? { ...item, [veld]: waarde } : item);
    setItems(nieuweLijst);
    setGeselecteerdItem({ ...geselecteerdItem, [veld]: waarde });
  }

  return (
    <div className="min-h-screen w-full bg-[#070B24] text-teal-200 py-14 px-8 flex flex-col items-center font-sans">
      <TaskFormModal open={open} setOpen={setOpen} onCreateTask={handleCreate} />

      <Card className="w-full max-w-7xl bg-[#0E153A]/60 backdrop-blur-2xl border border-teal-400/30 rounded-2xl shadow-2xl overflow-hidden">
        <div className="grid grid-cols-12 min-h-[750px]">
          
          {/* SIDEBAR */}
          <div className="col-span-3 border-r border-teal-400/10 bg-[#0b1233]/80 p-6">
            <Button onClick={() => setOpen(true)} className="w-full bg-teal-400 text-black font-bold mb-8 shadow-[0_0_15px_rgba(45,212,191,0.3)]">+ NIEUW DOC</Button>
            <div className="space-y-2 overflow-y-auto max-h-[600px]">
              {items.map((item) => (
                <div key={item.id} onClick={() => setGeselecteerdItem(item)} className={`p-4 rounded-lg cursor-pointer transition-all border ${geselecteerdItem?.id === item.id ? "border-teal-400 bg-teal-400/10" : "border-transparent bg-white/5 hover:bg-white/10"}`}>
                  <p className="text-xs font-bold uppercase tracking-tighter text-teal-500 mb-1">{item.documentType}</p>
                  <p className="font-bold text-sm truncate">{item.titel}</p>
                  <p className="text-[10px] opacity-40 mt-2">Sprint {item.sprint} • {item.datum}</p>
                </div>
              ))}
            </div>
          </div>

          {/* EDITOR */}
          <div className="col-span-9 p-16 bg-[#0E153A]/30">
            {geselecteerdItem ? (
              <div className="max-w-3xl mx-auto space-y-12 animate-in fade-in slide-in-from-bottom-4 duration-500">
                <div className="border-b border-teal-400/20 pb-6">
                  <h1 className="text-5xl font-black text-white tracking-tighter italic uppercase">{geselecteerdItem.titel}</h1>
                  <p className="text-teal-400 font-bold tracking-[0.3em] text-[10px] mt-2 opacity-60">Systeem: SCRUM_DOC_V1.0</p>
                </div>

                <div className="space-y-10">
                  {getQuestions(geselecteerdItem.documentType).map((q, index) => (
                    <div key={index}>
                      <label className="text-[11px] text-fuchsia-400 font-black mb-4 block uppercase tracking-widest">{q}</label>
                      <Textarea 
                        value={geselecteerdItem[`content${index + 1}`]} 
                        onChange={(e) => updateContent(`content${index + 1}`, e.target.value)}
                        placeholder="Schrijf hier..."
                        className="bg-transparent border-none focus-visible:ring-0 text-xl text-teal-100 p-0 min-h-[100px] resize-none placeholder:text-teal-900 shadow-none"
                      />
                    </div>
                  ))}
                </div>
              </div>
            ) : (
              <div className="h-full flex items-center justify-center opacity-10 grayscale italic font-black text-4xl uppercase tracking-[1em] -rotate-12 select-none">
                Scrum Docs
              </div>
            )}
          </div>

        </div>
      </Card>
    </div>
  );
}